#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
source "$HOME/.companyos_launch_env" 2>/dev/null || true

STAMP="$(date +%Y%m%d_%H%M%S)"
BK="$HOME/companyos/.companyos_backups/capability_expansion_v6_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/capability_expansion.py "$BK/"

echo "" | base64 -d > "$PREFIX/tmp/companyos_expansion_v6_patch.py"
python "$PREFIX/tmp/companyos_expansion_v6_patch.py"
rm -f "$PREFIX/tmp/companyos_expansion_v6_patch.py"

echo "" | base64 -d > tests/test_capability_expansion_generation_recovery_v6.py

echo "[1/6] Compile"
python -m py_compile companyos/runtime/capability_expansion.py tests/test_capability_expansion_generation_recovery_v6.py

echo "[2/6] Generation recovery tests"
python -m unittest tests.test_capability_expansion_generation_recovery_v6 -v

echo "[3/6] Run expansion cycle"
scripts/companyos_expandctl once | tee .companyos_runtime/capability_expansion_v6_cycle.json

echo "[4/6] Commit/push"
git add companyos/runtime/capability_expansion.py tests/test_capability_expansion_generation_recovery_v6.py
git diff --cached --quiet || git commit -m "Add retry and recovery for self-expansion generation"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "[5/6] Restart"
scripts/companyosctl restart || true
sleep 8

echo "[6/6] Verify"
echo "===== EXPANSION STATUS ====="
scripts/companyos_expandctl status || true
echo "===== INVENTORY ====="
scripts/companyos_expandctl inventory || true
echo "===== SERVICES ====="
scripts/companyosctl status || true

echo "BACKUP=$BK"
echo "COMPANYOS_CAPABILITY_EXPANSION_GENERATION_RECOVERY_V6=PASS"
